public static int findNthLeapYear(int Y, int N) {
    if (N <= 0) {
        return -1;
    }

    int year = Y;
    int count = 0;

    while (true) {
        year++;
        // Check if year is a leap year
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            count++;
            if (count == N) {
                return year;
            }
        }
    }
}

