public static int calculateTimeNeeded(int N) {
    if (N <= 0) {
        return 0;
    }

    if (N % 2 == 0) {
        return N;
    } else {
        // For odd N, the time is (N - 1) + (N - 3) + ... + 2
        // This is the sum of even numbers from 2 to N-1
        int k = (N - 1) / 2;
        return k * (k + 1);
    }
}

