public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;

    int[] dr = {-1, 1, 0, 0};
    int[] dc = {0, 0, -1, 1};

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                // BFS to mark all connected oil pockets
                java.util.LinkedList<int[]> queue = new java.util.LinkedList<>();
                queue.offer(new int[]{i, j});
                grid[i][j] = '*'; // Mark as visited by converting to '*'

                while (!queue.isEmpty()) {
                    int[] cell = queue.poll();
                    int r = cell[0];
                    int c = cell[1];

                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];

                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '@') {
                            grid[nr][nc] = '*'; // Mark as visited
                            queue.offer(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }

    return count;
}

