public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null) {
        throw new IllegalArgumentException("Start and end coordinates cannot be null");
    }
    if (start.length != end.length) {
        throw new IllegalArgumentException("Start and end coordinates must have the same length");
    }

    // Build adjacency list
    List<List<Integer>>[] graph = new List[n * n];
    for (int i = 0; i < graph.length; i++) {
        graph[i] = new ArrayList<>();
    }

    // Add paths to the graph
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 2) {
                continue;
            }
            int from = path[0];
            int to = path[1];
            if (from >= 0 && from < n * n && to >= 0 && to < n * n) {
                graph[from].add(to);
                graph[to].add(from); // Assuming undirected paths
            }
        }
    }

    // Helper method to convert 1D index to 2D coordinates
    int[] startCoord = new int[2];
    int[] endCoord = new int[2];

