            case Calendar.WEDNESDAY: weekdayName = "Wednesday"; break;
            case Calendar.THURSDAY: weekdayName = "Thursday"; break;
            case Calendar.FRIDAY: weekdayName = "Friday"; break;
            case Calendar.SATURDAY: weekdayName = "Saturday"; break;
            default: throw new IllegalArgumentException("Unknown day");
        }

