public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }

    int n = arr.length;
    // Calculate the number of elements to remove from each end (5%)
    int removeCount = n / 20;

    // If n is less than 20, remove 0 elements
    // Sort the array
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);

    // Sum the elements that remain after removing the smallest and largest 5%
    double sum = 0.0;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += sorted[i];
    }

    // Calculate the mean
    int remainingCount = n - 2 * removeCount;
    if (remainingCount == 0) {
        return 0.0;
    }

    return sum / remainingCount;
}

