public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false;
    }

    int[] modCount = new int[k];

    for (int num : arr) {
        int mod = ((num % k) + k) % k;
        modCount[mod]++;
    }

    // For remainder 0, we need an even number of elements
    if (modCount[0] % 2 != 0) {
        return false;
    }

    // Check pairs of remainders i and k-i
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) {
            // If two different remainders are the same (only possible when k is even and i == k/2)
            if (modCount[i] % 2 != 0) {
                return false;
            }
        } else {
            // The count of remainder i must equal the count of remainder k-i
            if (modCount[i] != modCount[k - i]) {
                return false;
            }
        }
    }

    return true;
}

