        return false;
    }

    int count = arr.length;
    int[] countOfRemainders = new int[k];

    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        countOfRemainders[remainder]++;
    }

    // Check for remainder 0: must be even count
    if (countOfRemainders[0] % 2 != 0) {
        return false;
    }

    // Check for remainders 1 to k-1
    for (int i = 1; i <= k / 2; i++) {
        int complement = k - i;
        if (i == complement) {
            // Remainder is half of k, must be even count
            if (countOfRemainders[i] % 2 != 0) {
                return false;
            }
        } else {
            // Remainders i and k-i must have equal counts
            if (countOfRemainders[i] != countOfRemainders[complement]) {
                return false;
            }
        }
    }

    return true;
}

