public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();

    while (result.length() < s.length()) {
        // Step 1-3: Pick smallest characters in increasing order
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
            }
        }

        // Step 4-6: Pick largest characters in decreasing order
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
            }
        }
    }

    return result.toString();
}

