public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }

    // dp[i] represents the minimum cost to reach step i
    // We can start at step 0 (with cost[0]) or step 1 (with cost[1])
    int[] dp = new int[n + 1];
    // The top is at index n, so we need to reach dp[n]
    // dp[0] = 0 (starting before step 0, no cost)
    // dp[1] = 0 (starting before step 1, no cost)
    // For i >= 2: dp[i] = min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2])
    // This works because to reach step i, you either came from step i-1 (paying cost[i-1])
    // or from step i-2 (paying cost[i-2])

    // Alternative approach: 
    // Let prev2 = min cost to reach 2 steps back, prev1 = min cost to reach 1 step back
    // Start: prev2 = 0 (cost to reach "step 0" in terms of position before first step), prev1 = 0
    // Actually, cleaner: 
    // dp[i] = min cost to reach step i (where step i costs cost[i] to step on)
    // But the problem says you start at index 0 or 1, paying their cost.
    // To reach the top (index n), you can come from index n-1 or n-2.

    int prev2 = 0; // min cost to reach position 0 (before any step)
    int prev1 = 0; // min cost to reach position 1
    // Actually, let's use the standard approach:
    // We want to reach index n (the top).
    // To reach index i, you can come from index i-1 (paying cost[i-1]) or index i-2 (paying cost[i-2]).
    // dp[0] = 0 (not actually stepping on any step yet, but at the ground)
    // dp[1] = 0
    // dp[i] = min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2]) for i >= 2

    int curr = 0;
    for (int i = 2; i <= n; i++) {
        curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }

    return prev1;
}

