public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0) {
        return false;
    }

    int n = s.length();
    if (k == 0) {
        return true;
    }

    if (n < k) {
        return false;
    }

    int totalNeeded = 1 << k;
    boolean[] seen = new boolean[totalNeeded];
    int count = 0;

    int mask = totalNeeded - 1;
    int current = 0;

    for (int i = 0; i < n; i++) {
        current = ((current << 1) | (s.charAt(i) - '0')) & mask;

        if (i >= k - 1) {
            if (!seen[current]) {
                seen[current] = true;
                count++;
                if (count == totalNeeded) {
                    return true;
                }
            }
        }
    }

    return false;
}

