public boolean hasAllCodes(String s, int k) {
    if (s == null || s.isEmpty()) {
        return k == 0;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }

    // Total number of binary strings of length k is 2^k
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;

    // Use a sliding window to generate all substrings of length k
    // Convert each substring to an integer
    int num = 0;
    for (int i = 0; i < n; i++) {
        num = (num << 1) | (s.charAt(i) - '0');
        if (i >= k) {
            // Remove the bit that fell out of the window from the left
            num &= total - 1; // This masks to keep only k bits
        }
        if (i >= k - 1) {
            // We now have a full window of length k
            if (!seen[num]) {
                count++;
                seen[num] = true;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

