public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k || k == 0) {
        return true;
    }

    int totalRequired = 1 << k;
    if (s.length() < k || s.length() - k + 1 < totalRequired) {
        return false;
    }

    boolean[] seen = new boolean[totalRequired];
    int bitmask = 0;

    for (int i = 0; i < s.length(); i++) {
        bitmask = (bitmask << 1) | (s.charAt(i) - '0');
        if (i >= k) {
            bitmask &= (1 << k) - 1;
            seen[bitmask] = true;
        }
    }

    for (int i = 0; i < totalRequired; i++) {
        if (!seen[i]) {
            return false;
        }
    }

    return true;
}

