public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int insertions = 0;
    int openNeeded = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            openNeeded++;
        } else {
            if (openNeeded > 0) {
                openNeeded--;
            } else {
                insertions++;
            }
        }
    }

    return insertions + openNeeded;
}

