public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int needOpen = 0; // number of '(' we need to add
    int needClose = 0; // number of ')' we need to add
    int openCount = 0; // count of unmatched '(' we have seen so far

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            openCount++;
        } else {
            // it's a ')'
            if (openCount > 0) {
                openCount--;
            } else {
                needClose++;
            }
        }
    }

    // Even after processing all characters, if there are unmatched '('
    // we need to add that many ')' to balance them
    needOpen = openCount;

    return needOpen + needClose;
}

