public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Use a stack-like approach with a StringBuilder
    StringBuilder sb = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        // If the stack is not empty, check if the top character and current character form a bad pair
        if (sb.length() > 0) {
            char top = sb.charAt(sb.length() - 1);
            // A bad pair is when one is lowercase and the other is the corresponding uppercase
            // Two characters are the same letter in different cases if their difference is 32 (in ASCII)
            // and they are not the same character
            if (Math.abs(c - top) == 32) {
                // Remove the top character (they cancel out)
                sb.deleteCharAt(sb.length() - 1);
                continue;
            }
        }

        // Add the current character to the stack
        sb.append(c);
    }

    return sb.toString();
}

