    }

    long ones = 0;
    long twos = 0;
    long threes = 0;

    for (int num : nums) {
        long mask = 1L << num;
        // Ignore bits that are already in twos or threes
        long tmp = ones + mask;
        twos += ones & mask;
        ones = tmp & ~(twos | threes);
        threes += twos & (tmp - twos);
        // Reset three-count to zero to maintain invariant
        twos &= ~threes;
        threes = 0;
    }

    // Convert ones and zeros result using bit count
    // Since we're using a 64-bit long, we need to find the bit that is set only once
    long result = ones & ~twos;

    for (int i = 0; i < 64; i++) {
        if ((result & 1) != 0) {
            return i;
        }
        result >>= 1;
    }

    return 0;
}

