public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();

    // Handle the case where low is 0
    if (low == 0) {
        result.add(0);
        low = 1;
    }

    // Use BFS to generate stepping numbers
    Queue<Integer> queue = new LinkedList<>();

    // Initialize with all single digits from 1 to 9
    for (int i = 1; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int current = queue.poll();
        int lastDigit = current % 10;

        // Generate next numbers by adding digits that differ by 1
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                if (next >= low) {
                    result.add((int) next);
                }
                queue.offer((int) next);
