        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                if (next >= low) {
                    result.add((int) next);
                }
                queue.offer((int) next);
            }
        }
    }

    // Sort the result to ensure ascending order
    Collections.sort(result);

    return result;
}

