        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    // dp[i][j][k] where k represents the direction:
    // 0: horizontal, 1: vertical, 2: diagonal, 3: anti-diagonal
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // horizontal
                dp[i][j][0] = (j > 0) ? dp[i][j - 1][0] + 1 : 1;
                // vertical
                dp[i][j][1] = (i > 0) ? dp[i - 1][j][1] + 1 : 1;
                // diagonal
                dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1;
                // anti-diagonal
                dp[i][j][3] = (i > 0 && j < n - 1) ? dp[i - 1][j + 1][3] + 1 : 1;

