public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);

        if (current * 10 <= n) {
            // Can go deeper
            current = current * 10;
        } else {
            // Cannot go deeper, try to go right
            while (current > 0 && current % 10 == 9 || current == n) {
                current = current / 10;
            }
            // If current is now 0, it means we've exhausted all leaves from 9 upward
            // But we need to increment the last digit if possible
            if (current > 0) {
                current++;
            }
        }
    }

    return result;
}

