public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // We'll use a list of perfect squares up to n
    // We can use a DP approach: dp[i] = minimum number of perfect square numbers that sum up to i
    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        // Try every perfect square that is less than or equal to i
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }

    return dp[n];
}

